TWComponent.script:
switch (tw.local.odcRequest.stepLog.action) {
    case String(tw.epv.CreationActions.createContract):
        tw.local.action = "create";
        break;
    case String(tw.epv.CreationActions.amendContract):
        tw.local.action = "amend";
        break;
    case String(tw.epv.CreationActions.recreateContract):
        tw.local.action = "recreate";
        break;
    default:
        tw.local.action = "";
        break;
}

processPrePosts.script:
if (tw.local.isSuccessful == true) {
	tw.local.status = "Contract Created Successfully"
}else{
	tw.local.status = "Contract Creation Failed"
}

tw.local.serviceName = "MW Close BC Contract"


var contNum2 = tw.local.odcRequest.BasicDetails.flexCubeContractNo2;
var contNum1 = tw.local.odcRequest.BasicDetails.flexCubeContractNo;

tw.local.latestFlexCubeNum = contNum2 || contNum1;

